    if (nc < 16) nc = 16;
    if (nc > (int64_t)RT_STR_MAX) nc = n;
    char* q = rt_alloc((size_t)nc + 1);
    memcpy(q, RT_SP(*s), (size_t)s->len);
    memcpy(q + s->len, bp, (size_t)b.len);
    q[n] = 0;
    if (s->cap) rt_free(s->p);
    s->p = q;
    s->cap = (uint32_t)nc;
    s->len = (uint32_t)n;
