                rt_v32 x1 = rt_v32_at(p + 32 + i1), y1 = rt_v32_at(p + 32 + i2);
                rt_v32 r0 = ((x0 == a0) | (x0 == a1)) & ((y0 == b0) | (y0 == b1));
