#define top16 top16__log2
/*
 * Double-precision log2(x) function.
 *
 * Copyright (c) 2018, Arm Limited.
 * SPDX-License-Identifier: MIT
 */

#define T __log2_data.tab
#define T2 __log2_data.tab2
