static char sl7198b[44] = "/* ---- musl 1.2.5 src/math/expm1.c ---- */";
static const lxl_str sl7198 = {.p = sl7198b, .len = 43U, .cap = 0U};
static char sl7199b[19] = "#define R R__expm1";
static const lxl_str sl7199 = {.p = sl7199b, .len = 18U, .cap = 0U};
static char sl7200b[29] = "#define ln2_hi ln2_hi__expm1";
static const lxl_str sl7200 = {.p = sl7200b, .len = 28U, .cap = 0U};
static char sl7201b[29] = "#define ln2_lo ln2_lo__expm1";
static const lxl_str sl7201 = {.p = sl7201b, .len = 28U, .cap = 0U};
static char sl7202b[54] = "/* origin: FreeBSD /usr/src/lib/msun/src/s_expm1.c */";
static const lxl_str sl7202 = {.p = sl7202b, .len = 53U, .cap = 0U};
static char sl7203b[56] = " * ====================================================";
static const lxl_str sl7203 = {.p = sl7203b, .len = 55U, .cap = 0U};
static char sl7204b[69] = " * Copyright (C) 1993 by Sun Microsystems, Inc. All rights reserved.";
static const lxl_str sl7204 = {.p = sl7204b, .len = 68U, .cap = 0U};
static char sl7205b[59] = " * Developed at SunPro, a Sun Microsystems, Inc. business.";
static const lxl_str sl7205 = {.p = sl7205b, .len = 58U, .cap = 0U};
static char sl7206b[56] = " * Permission to use, copy, modify, and distribute this";
static const lxl_str sl7206 = {.p = sl7206b, .len = 55U, .cap = 0U};
static char sl7207b[57] = " * software is freely granted, provided that this notice";
static const lxl_str sl7207 = {.p = sl7207b, .len = 56U, .cap = 0U};
static char sl7208b[17] = " * is preserved.";
static const lxl_str sl7208 = {.p = sl7208b, .len = 16U, .cap = 0U};
static char sl7209b[12] = "/* expm1(x)";
static const lxl_str sl7209 = {.p = sl7209b, .len = 11U, .cap = 0U};
static char sl7210b[51] = " * Returns exp(x)-1, the exponential of x minus 1.";
static const lxl_str sl7210 = {.p = sl7210b, .len = 50U, .cap = 0U};
static char sl7211b[10] = " * Method";
static const lxl_str sl7211 = {.p = sl7211b, .len = 9U, .cap = 0U};
static char sl7212b[28] = " *   1. Argument reduction:";
static const lxl_str sl7212 = {.p = sl7212b, .len = 27U, .cap = 0U};
static char sl7213b[48] = " *      Given x, find r and integer k such that";
static const lxl_str sl7213 = {.p = sl7213b, .len = 47U, .cap = 0U};
static char sl7214b[58] = " *               x = k*ln2 + r,  |r| <= 0.5*ln2 ~ 0.34658";
static const lxl_str sl7214 = {.p = sl7214b, .len = 57U, .cap = 0U};
static char sl7215b[64] = " *      Here a correction term c will be computed to compensate";
static const lxl_str sl7215 = {.p = sl7215b, .len = 63U, .cap = 0U};
static char sl7216b[64] = " *      the error in r when rounded to a floating-point number.";
static const lxl_str sl7216 = {.p = sl7216b, .len = 63U, .cap = 0U};
static char sl7217b[65] = " *   2. Approximating expm1(r) by a special rational function on";
static const lxl_str sl7217 = {.p = sl7217b, .len = 64U, .cap = 0U};
static char sl7218b[34] = " *      the interval [0,0.34658]:";
static const lxl_str sl7218 = {.p = sl7218b, .len = 33U, .cap = 0U};
static char sl7219b[14] = " *      Since";
static const lxl_str sl7219 = {.p = sl7219b, .len = 13U, .cap = 0U};
static char sl7220b[63] = " *          r*(exp(r)+1)/(exp(r)-1) = 2+ r^2/6 - r^4/360 + ...";
static const lxl_str sl7220 = {.p = sl7220b, .len = 62U, .cap = 0U};
static char sl7221b[29] = " *      we define R1(r*r) by";
static const lxl_str sl7221 = {.p = sl7221b, .len = 28U, .cap = 0U};
static char sl7222b[57] = " *          r*(exp(r)+1)/(exp(r)-1) = 2+ r^2/6 * R1(r*r)";
static const lxl_str sl7222 = {.p = sl7222b, .len = 56U, .cap = 0U};
static char sl7223b[17] = " *      That is,";
static const lxl_str sl7223 = {.p = sl7223b, .len = 16U, .cap = 0U};
static char sl7224b[58] = " *          R1(r**2) = 6/r *((exp(r)+1)/(exp(r)-1) - 2/r)";
static const lxl_str sl7224 = {.p = sl7224b, .len = 57U, .cap = 0U};
static char sl7225b[61] = " *                   = 6/r * ( 1 + 2.0*(1/(exp(r)-1) - 1/r))";
static const lxl_str sl7225 = {.p = sl7225b, .len = 60U, .cap = 0U};
static char sl7226b[64] = " *                   = 1 - r^2/60 + r^4/2520 - r^6/100800 + ...";
static const lxl_str sl7226 = {.p = sl7226b, .len = 63U, .cap = 0U};
static char sl7227b[66] = " *      We use a special Remez algorithm on [0,0.347] to generate";
static const lxl_str sl7227 = {.p = sl7227b, .len = 65U, .cap = 0U};
static char sl7228b[63] = " *      a polynomial of degree 5 in r*r to approximate R1. The";
static const lxl_str sl7228 = {.p = sl7228b, .len = 62U, .cap = 0U};
static char sl7229b[66] = " *      maximum error of this polynomial approximation is bounded";
static const lxl_str sl7229 = {.p = sl7229b, .len = 65U, .cap = 0U};
static char sl7230b[35] = " *      by 2**-61. In other words,";
static const lxl_str sl7230 = {.p = sl7230b, .len = 34U, .cap = 0U};
static char sl7231b[71] = " *          R1(z) ~ 1.0 + Q1*z + Q2*z**2 + Q3*z**3 + Q4*z**4 + Q5*z**5";
static const lxl_str sl7231 = {.p = sl7231b, .len = 70U, .cap = 0U};
static char sl7232b[50] = " *      where   Q1  =  -1.6666666666666567384E-2,";
static const lxl_str sl7232 = {.p = sl7232b, .len = 49U, .cap = 0U};
static char sl7233b[50] = " *              Q2  =   3.9682539681370365873E-4,";
static const lxl_str sl7233 = {.p = sl7233b, .len = 49U, .cap = 0U};
static char sl7234b[50] = " *              Q3  =  -9.9206344733435987357E-6,";
static const lxl_str sl7234 = {.p = sl7234b, .len = 49U, .cap = 0U};
static char sl7235b[50] = " *              Q4  =   2.5051361420808517002E-7,";
static const lxl_str sl7235 = {.p = sl7235b, .len = 49U, .cap = 0U};
static char sl7236b[50] = " *              Q5  =  -6.2843505682382617102E-9;";
static const lxl_str sl7236 = {.p = sl7236b, .len = 49U, .cap = 0U};
static char sl7237b[28] = " *              z   =  r*r,";
static const lxl_str sl7237 = {.p = sl7237b, .len = 27U, .cap = 0U};
static char sl7238b[30] = " *      with error bounded by";
static const lxl_str sl7238 = {.p = sl7238b, .len = 29U, .cap = 0U};
static char sl7239b[53] = " *          |                  5           |     -61";
static const lxl_str sl7239 = {.p = sl7239b, .len = 52U, .cap = 0U};
static char sl7240b[50] = " *          | 1.0+Q1*z+...+Q5*z   -  R1(z) | <= 2";
static const lxl_str sl7240 = {.p = sl7240b, .len = 49U, .cap = 0U};
static char sl7241b[45] = " *          |                              |";
static const lxl_str sl7241 = {.p = sl7241b, .len = 44U, .cap = 0U};
static char sl7242b[62] = " *      expm1(r) = exp(r)-1 is then computed by the following";
static const lxl_str sl7242 = {.p = sl7242b, .len = 61U, .cap = 0U};
static char sl7243b[69] = " *      specific way which minimize the accumulation rounding error:";
static const lxl_str sl7243 = {.p = sl7243b, .len = 68U, .cap = 0U};
static char sl7244b[39] = " *                             2     3";
static const lxl_str sl7244 = {.p = sl7244b, .len = 38U, .cap = 0U};
static char sl7245b[64] = " *                            r     r    [ 3 - (R1 + R1*r/2)  ]";
static const lxl_str sl7245 = {.p = sl7245b, .len = 63U, .cap = 0U};
static char sl7246b[64] = " *            expm1(r) = r + --- + --- * [--------------------]";
static const lxl_str sl7246 = {.p = sl7246b, .len = 63U, .cap = 0U};
static char sl7247b[64] = " *                            2     2    [ 6 - r*(3 - R1*r/2) ]";
static const lxl_str sl7247 = {.p = sl7247b, .len = 63U, .cap = 0U};
static char sl7248b[66] = " *      To compensate the error in the argument reduction, we use";
static const lxl_str sl7248 = {.p = sl7248b, .len = 65U, .cap = 0U};
static char sl7249b[55] = " *              expm1(r+c) = expm1(r) + c + expm1(r)*c";
static const lxl_str sl7249 = {.p = sl7249b, .len = 54U, .cap = 0U};
static char sl7250b[48] = " *                         ~ expm1(r) + c + r*c";
static const lxl_str sl7250 = {.p = sl7250b, .len = 47U, .cap = 0U};
static char sl7251b[64] = " *      Thus c+r*c will be added in as the correction terms for";
static const lxl_str sl7251 = {.p = sl7251b, .len = 63U, .cap = 0U};
static char sl7252b[65] = " *      expm1(r+c). Now rearrange the term to avoid optimization";
static const lxl_str sl7252 = {.p = sl7252b, .len = 64U, .cap = 0U};
static char sl7253b[18] = " *      screw up:";
static const lxl_str sl7253 = {.p = sl7253b, .len = 17U, .cap = 0U};
static char sl7254b[72] = " *                      (      2                                    2 )";
static const lxl_str sl7254 = {.p = sl7254b, .len = 71U, .cap = 0U};
static char sl7255b[72] = " *                      ({  ( r    [ R1 -  (3 - R1*r/2) ]  )  }    r  )";
static const lxl_str sl7255 = {.p = sl7255b, .len = 71U, .cap = 0U};
static char sl7256b[72] = " *       expm1(r+c)~r - ({r*(--- * [--------------------]-c)-c} - --- )";
static const lxl_str sl7256 = {.p = sl7256b, .len = 71U, .cap = 0U};
static char sl7257b[72] = " *                      ({  ( 2    [ 6 - r*(3 - R1*r/2) ]  )  }    2  )";
static const lxl_str sl7257 = {.p = sl7257b, .len = 71U, .cap = 0U};
static char sl7258b[72] = " *                      (                                             )";
static const lxl_str sl7258 = {.p = sl7258b, .len = 71U, .cap = 0U};
static char sl7259b[27] = " *                 = r - E";
static const lxl_str sl7259 = {.p = sl7259b, .len = 26U, .cap = 0U};
static char sl7260b[39] = " *   3. Scale back to obtain expm1(x):";
static const lxl_str sl7260 = {.p = sl7260b, .len = 38U, .cap = 0U};
static char sl7261b[29] = " *      From step 1, we have";
static const lxl_str sl7261 = {.p = sl7261b, .len = 28U, .cap = 0U};
static char sl7262b[50] = " *         expm1(x) = either 2^k*[expm1(r)+1] - 1";
static const lxl_str sl7262 = {.p = sl7262b, .len = 49U, .cap = 0U};
static char sl7263b[55] = " *                  = or     2^k*[expm1(r) + (1-2^-k)]";
static const lxl_str sl7263 = {.p = sl7263b, .len = 54U, .cap = 0U};
static char sl7264b[30] = " *   4. Implementation notes:";
static const lxl_str sl7264 = {.p = sl7264b, .len = 29U, .cap = 0U};
static char sl7265b[69] = " *      (A). To save one multiplication, we scale the coefficient Qi";
static const lxl_str sl7265 = {.p = sl7265b, .len = 68U, .cap = 0U};
static char sl7266b[50] = " *           to Qi*2^i, and replace z by (x^2)/2.";
static const lxl_str sl7266 = {.p = sl7266b, .len = 49U, .cap = 0U};
static char sl7267b[65] = " *      (B). To achieve maximum accuracy, we compute expm1(x) by";
static const lxl_str sl7267 = {.p = sl7267b, .len = 64U, .cap = 0U};
static char sl7268b[71] = " *        (i)   if x < -56*ln2, return -1.0, (raise inexact if x!=inf)";
static const lxl_str sl7268 = {.p = sl7268b, .len = 70U, .cap = 0U};
static char sl7269b[35] = " *        (ii)  if k=0, return r-E";
static const lxl_str sl7269 = {.p = sl7269b, .len = 34U, .cap = 0U};
static char sl7270b[46] = " *        (iii) if k=-1, return 0.5*(r-E)-0.5";
static const lxl_str sl7270 = {.p = sl7270b, .len = 45U, .cap = 0U};
static char sl7271b[59] = " *        (iv)  if k=1 if r < -0.25, return 2*((r+0.5)- E)";
static const lxl_str sl7271 = {.p = sl7271b, .len = 58U, .cap = 0U};
static char sl7272b[60] = " *                     else          return  1.0+2.0*(r-E);";
static const lxl_str sl7272 = {.p = sl7272b, .len = 59U, .cap = 0U};
static char sl7273b[70] = " *        (v)   if (k<-2||k>56) return 2^k(1-(E-r)) - 1 (or exp(x)-1)";
static const lxl_str sl7273 = {.p = sl7273b, .len = 69U, .cap = 0U};
static char sl7274b[61] = " *        (vi)  if k <= 20, return 2^k((1-2^-k)-(E-r)), else";
static const lxl_str sl7274 = {.p = sl7274b, .len = 60U, .cap = 0U};
static char sl7275b[43] = " *        (vii) return 2^k(1-((E+2^-k)-r))";
static const lxl_str sl7275 = {.p = sl7275b, .len = 42U, .cap = 0U};
static char sl7276b[18] = " * Special cases:";
static const lxl_str sl7276 = {.p = sl7276b, .len = 17U, .cap = 0U};
static char sl7277b[46] = " *      expm1(INF) is INF, expm1(NaN) is NaN;";
static const lxl_str sl7277 = {.p = sl7277b, .len = 45U, .cap = 0U};
static char sl7278b[31] = " *      expm1(-INF) is -1, and";
static const lxl_str sl7278 = {.p = sl7278b, .len = 30U, .cap = 0U};
static char sl7279b[55] = " *      for finite argument, only expm1(0)=0 is exact.";
static const lxl_str sl7279 = {.p = sl7279b, .len = 54U, .cap = 0U};
static char sl7280b[13] = " * Accuracy:";
static const lxl_str sl7280 = {.p = sl7280b, .len = 12U, .cap = 0U};
static char sl7281b[70] = " *      according to an error analysis, the error is always less than";
static const lxl_str sl7281 = {.p = sl7281b, .len = 69U, .cap = 0U};
static char sl7282b[40] = " *      1 ulp (unit in the last place).";
static const lxl_str sl7282 = {.p = sl7282b, .len = 39U, .cap = 0U};
static char sl7283b[15] = " * Misc. info.";
static const lxl_str sl7283 = {.p = sl7283b, .len = 14U, .cap = 0U};
static char sl7284b[24] = " *      For IEEE double";
static const lxl_str sl7284 = {.p = sl7284b, .len = 23U, .cap = 0U};
static char sl7285b[70] = " *          if x >  7.09782712893383973096e+02 then expm1(x) overflow";
static const lxl_str sl7285 = {.p = sl7285b, .len = 69U, .cap = 0U};
static char sl7286b[14] = " * Constants:";
static const lxl_str sl7286 = {.p = sl7286b, .len = 13U, .cap = 0U};
static char sl7287b[66] = " * The hexadecimal values are the intended ones for the following";
static const lxl_str sl7287 = {.p = sl7287b, .len = 65U, .cap = 0U};
static char sl7288b[64] = " * constants. The decimal values may be used, provided that the";
static const lxl_str sl7288 = {.p = sl7288b, .len = 63U, .cap = 0U};
static char sl7289b[66] = " * compiler will convert from decimal to binary accurately enough";
static const lxl_str sl7289 = {.p = sl7289b, .len = 65U, .cap = 0U};
static char sl7290b[44] = " * to produce the hexadecimal values shown.";
static const lxl_str sl7290 = {.p = sl7290b, .len = 43U, .cap = 0U};
static char sl7291b[20] = "static const double";
static const lxl_str sl7291 = {.p = sl7291b, .len = 19U, .cap = 0U};
