static const lxl_str sl7292 = {.p = sl7292b, .len = 70U, .cap = 0U};
static char sl7293b[71] = "ln2_hi      = 6.93147180369123816490e-01, /* 0x3fe62e42, 0xfee00000 */";
static const lxl_str sl7293 = {.p = sl7293b, .len = 70U, .cap = 0U};
static char sl7294b[71] = "ln2_lo      = 1.90821492927058770002e-10, /* 0x3dea39ef, 0x35793c76 */";
static const lxl_str sl7294 = {.p = sl7294b, .len = 70U, .cap = 0U};
static char sl7295b[71] = "invln2      = 1.44269504088896338700e+00, /* 0x3ff71547, 0x652b82fe */";
static const lxl_str sl7295 = {.p = sl7295b, .len = 70U, .cap = 0U};
static char sl7296b[79] = "/* Scaled Q's: Qn_here = 2**n * Qn_above, for R(2*z) where z = hxs = x*x/2: */";
static const lxl_str sl7296 = {.p = sl7296b, .len = 78U, .cap = 0U};
