static char sl7387b[26] = "/* double log1p(double x)";
static const lxl_str sl7387 = {.p = sl7387b, .len = 25U, .cap = 0U};
static char sl7388b[40] = " * Return the natural logarithm of 1+x.";
static const lxl_str sl7388 = {.p = sl7388b, .len = 39U, .cap = 0U};
static char sl7389b[12] = " * Method :";
static const lxl_str sl7389 = {.p = sl7389b, .len = 11U, .cap = 0U};
static char sl7390b[51] = " *   1. Argument Reduction: find k and f such that";
static const lxl_str sl7390 = {.p = sl7390b, .len = 50U, .cap = 0U};
static char sl7391b[43] = " *                      1+x = 2^k * (1+f),";
static const lxl_str sl7391 = {.p = sl7391b, .len = 42U, .cap = 0U};
static char sl7392b[46] = " *         where  sqrt(2)/2 < 1+f < sqrt(2) .";
static const lxl_str sl7392 = {.p = sl7392b, .len = 45U, .cap = 0U};
static char sl7393b[66] = " *      Note. If k=0, then f=x is exact. However, if k!=0, then f";
static const lxl_str sl7393 = {.p = sl7393b, .len = 65U, .cap = 0U};
static char sl7394b[69] = " *      may not be representable exactly. In that case, a correction";
static const lxl_str sl7394 = {.p = sl7394b, .len = 68U, .cap = 0U};
static char sl7395b[63] = " *      term is need. Let u=1+x rounded. Let c = (1+x)-u, then";
static const lxl_str sl7395 = {.p = sl7395b, .len = 62U, .cap = 0U};
static char sl7396b[69] = " *      log(1+x) - log(u) ~ c/u. Thus, we proceed to compute log(u),";
static const lxl_str sl7396 = {.p = sl7396b, .len = 68U, .cap = 0U};
static char sl7397b[46] = " *      and add back the correction term c/u.";
static const lxl_str sl7397 = {.p = sl7397b, .len = 45U, .cap = 0U};
static char sl7398b[61] = " *      (Note: when x > 2**53, one can simply return log(x))";
static const lxl_str sl7398 = {.p = sl7398b, .len = 60U, .cap = 0U};
static char sl7399b[45] = " *   2. Approximation of log(1+f): See log.c";
static const lxl_str sl7399 = {.p = sl7399b, .len = 44U, .cap = 0U};
static char sl7400b[62] = " *   3. Finally, log1p(x) = k*ln2 + log(1+f) + c/u. See log.c";
static const lxl_str sl7400 = {.p = sl7400b, .len = 61U, .cap = 0U};
static char sl7401b[65] = " *      log1p(x) is NaN with signal if x < -1 (including -INF) ;";
static const lxl_str sl7401 = {.p = sl7401b, .len = 64U, .cap = 0U};
static char sl7402b[60] = " *      log1p(+INF) is +INF; log1p(-1) is -INF with signal;";
static const lxl_str sl7402 = {.p = sl7402b, .len = 59U, .cap = 0U};
static char sl7403b[47] = " *      log1p(NaN) is that NaN with no signal.";
static const lxl_str sl7403 = {.p = sl7403b, .len = 46U, .cap = 0U};
static char sl7404b[62] = " * Note: Assuming log() return accurate answer, the following";
static const lxl_str sl7404 = {.p = sl7404b, .len = 61U, .cap = 0U};
static char sl7405b[72] = " *       algorithm can be used to compute log1p(x) to within a few ULP:";
static const lxl_str sl7405 = {.p = sl7405b, .len = 71U, .cap = 0U};
static char sl7406b[25] = " *              u = 1+x;";
static const lxl_str sl7406 = {.p = sl7406b, .len = 24U, .cap = 0U};
static char sl7407b[43] = " *              if(u==1.0) return x ; else";
static const lxl_str sl7407 = {.p = sl7407b, .len = 42U, .cap = 0U};
static char sl7408b[54] = " *                         return log(u)*(x/(u-1.0));";
static const lxl_str sl7408 = {.p = sl7408b, .len = 53U, .cap = 0U};
static char sl7409b[56] = " *       See HP-15C Advanced Functions Handbook, p.193.";
static const lxl_str sl7409 = {.p = sl7409b, .len = 55U, .cap = 0U};
static char sl7410b[62] = "ln2_hi = 6.93147180369123816490e-01,  /* 3fe62e42 fee00000 */";
