static char sl7469b[55] = "/* ---- musl 1.2.5 src/math/__rem_pio2_large.c ---- */";
static const lxl_str sl7469 = {.p = sl7469b, .len = 54U, .cap = 0U};
static char sl7470b[57] = "/* origin: FreeBSD /usr/src/lib/msun/src/k_rem_pio2.c */";
static const lxl_str sl7470 = {.p = sl7470b, .len = 56U, .cap = 0U};
static char sl7471b[60] = " * Developed at SunSoft, a Sun Microsystems, Inc. business.";
static const lxl_str sl7471 = {.p = sl7471b, .len = 59U, .cap = 0U};
static char sl7472b[36] = " * __rem_pio2_large(x,y,e0,nx,prec)";
static const lxl_str sl7472 = {.p = sl7472b, .len = 35U, .cap = 0U};
static char sl7473b[35] = " * double x[],y[]; int e0,nx,prec;";
static const lxl_str sl7473 = {.p = sl7473b, .len = 34U, .cap = 0U};
static char sl7474b[59] = " * __rem_pio2_large return the last three digits of N with";
static const lxl_str sl7474 = {.p = sl7474b, .len = 58U, .cap = 0U};
static char sl7475b[31] = " *              y = x - N*pi/2";
static const lxl_str sl7475 = {.p = sl7475b, .len = 30U, .cap = 0U};
static char sl7476b[23] = " * so that |y| < pi/2.";
static const lxl_str sl7476 = {.p = sl7476b, .len = 22U, .cap = 0U};
static char sl7477b[70] = " * The method is to compute the integer (mod 8) and fraction parts of";
static const lxl_str sl7477 = {.p = sl7477b, .len = 69U, .cap = 0U};
static char sl7478b[65] = " * (2/pi)*x without doing the full multiplication. In general we";
static const lxl_str sl7478 = {.p = sl7478b, .len = 64U, .cap = 0U};
static char sl7479b[70] = " * skip the part of the product that are known to be a huge integer (";
static const lxl_str sl7479 = {.p = sl7479b, .len = 69U, .cap = 0U};
static char sl7480b[67] = " * more accurately, = 0 mod 8 ). Thus the number of operations are";
static const lxl_str sl7480 = {.p = sl7480b, .len = 66U, .cap = 0U};
static char sl7481b[45] = " * independent of the exponent of the input.";
static const lxl_str sl7481 = {.p = sl7481b, .len = 44U, .cap = 0U};
static char sl7482b[68] = " * (2/pi) is represented by an array of 24-bit integers in ipio2[].";
static const lxl_str sl7482 = {.p = sl7482b, .len = 67U, .cap = 0U};
static char sl7483b[21] = " * Input parameters:";
static const lxl_str sl7483 = {.p = sl7483b, .len = 20U, .cap = 0U};
static char sl7484b[69] = " *      x[]     The input value (must be positive) is broken into nx";
static const lxl_str sl7484 = {.p = sl7484b, .len = 68U, .cap = 0U};
static char sl7485b[70] = " *              pieces of 24-bit integers in double precision format.";
static const lxl_str sl7485 = {.p = sl7485b, .len = 69U, .cap = 0U};
static char sl7486b[71] = " *              x[i] will be the i-th 24 bit of x. The scaled exponent";
static const lxl_str sl7486 = {.p = sl7486b, .len = 70U, .cap = 0U};
static char sl7487b[72] = " *              of x[0] is given in input parameter e0 (i.e., x[0]*2^e0";
static const lxl_str sl7487 = {.p = sl7487b, .len = 71U, .cap = 0U};
static char sl7488b[41] = " *              match x's up to 24 bits.";
static const lxl_str sl7488 = {.p = sl7488b, .len = 40U, .cap = 0U};
static char sl7489b[77] = " *              Example of breaking a double positive z into x[0]+x[1]+x[2]:";
static const lxl_str sl7489 = {.p = sl7489b, .len = 76U, .cap = 0U};
static char sl7490b[41] = " *                      e0 = ilogb(z)-23";
static const lxl_str sl7490 = {.p = sl7490b, .len = 40U, .cap = 0U};
static char sl7491b[43] = " *                      z  = scalbn(z,-e0)";
static const lxl_str sl7491 = {.p = sl7491b, .len = 42U, .cap = 0U};
static char sl7492b[30] = " *              for i = 0,1,2";
static const lxl_str sl7492 = {.p = sl7492b, .len = 29U, .cap = 0U};
static char sl7493b[40] = " *                      x[i] = floor(z)";
static const lxl_str sl7493 = {.p = sl7493b, .len = 39U, .cap = 0U};
static char sl7494b[46] = " *                      z    = (z-x[i])*2**24";
static const lxl_str sl7494 = {.p = sl7494b, .len = 45U, .cap = 0U};
static char sl7495b[70] = " *      y[]     ouput result in an array of double precision numbers.";
static const lxl_str sl7495 = {.p = sl7495b, .len = 69U, .cap = 0U};
static char sl7496b[41] = " *              The dimension of y[] is:";
static const lxl_str sl7496 = {.p = sl7496b, .len = 40U, .cap = 0U};
static char sl7497b[50] = " *                      24-bit  precision       1";
static const lxl_str sl7497 = {.p = sl7497b, .len = 49U, .cap = 0U};
static char sl7498b[50] = " *                      53-bit  precision       2";
static const lxl_str sl7498 = {.p = sl7498b, .len = 49U, .cap = 0U};
static char sl7499b[50] = " *                      64-bit  precision       2";
static const lxl_str sl7499 = {.p = sl7499b, .len = 49U, .cap = 0U};
static char sl7500b[50] = " *                      113-bit precision       3";
static const lxl_str sl7500 = {.p = sl7500b, .len = 49U, .cap = 0U};
static char sl7501b[70] = " *              The actual value is the sum of them. Thus for 113-bit";
static const lxl_str sl7501 = {.p = sl7501b, .len = 69U, .cap = 0U};
static char sl7502b[61] = " *              precison, one may have to do something like:";
static const lxl_str sl7502 = {.p = sl7502b, .len = 60U, .cap = 0U};
static char sl7503b[48] = " *              long double t,w,r_head, r_tail;";
static const lxl_str sl7503 = {.p = sl7503b, .len = 47U, .cap = 0U};
static char sl7504b[59] = " *              t = (long double)y[2] + (long double)y[1];";
static const lxl_str sl7504 = {.p = sl7504b, .len = 58U, .cap = 0U};
static char sl7505b[39] = " *              w = (long double)y[0];";
static const lxl_str sl7505 = {.p = sl7505b, .len = 38U, .cap = 0U};
static char sl7506b[30] = " *              r_head = t+w;";
static const lxl_str sl7506 = {.p = sl7506b, .len = 29U, .cap = 0U};
static char sl7507b[43] = " *              r_tail = w - (r_head - t);";
static const lxl_str sl7507 = {.p = sl7507b, .len = 42U, .cap = 0U};
static char sl7508b[70] = " *      e0      The exponent of x[0]. Must be <= 16360 or you need to";
static const lxl_str sl7508 = {.p = sl7508b, .len = 69U, .cap = 0U};
static char sl7509b[40] = " *              expand the ipio2 table.";
static const lxl_str sl7509 = {.p = sl7509b, .len = 39U, .cap = 0U};
static char sl7510b[33] = " *      nx      dimension of x[]";
static const lxl_str sl7510 = {.p = sl7510b, .len = 32U, .cap = 0U};
static char sl7511b[53] = " *      prec    an integer indicating the precision:";
static const lxl_str sl7511 = {.p = sl7511b, .len = 52U, .cap = 0U};
static char sl7512b[50] = " *                      0       24  bits (single)";
static const lxl_str sl7512 = {.p = sl7512b, .len = 49U, .cap = 0U};
static char sl7513b[50] = " *                      1       53  bits (double)";
static const lxl_str sl7513 = {.p = sl7513b, .len = 49U, .cap = 0U};
static char sl7514b[52] = " *                      2       64  bits (extended)";
static const lxl_str sl7514 = {.p = sl7514b, .len = 51U, .cap = 0U};
static char sl7515b[48] = " *                      3       113 bits (quad)";
static const lxl_str sl7515 = {.p = sl7515b, .len = 47U, .cap = 0U};
static char sl7516b[22] = " * External function:";
static const lxl_str sl7516 = {.p = sl7516b, .len = 21U, .cap = 0U};
static char sl7517b[34] = " *      double scalbn(), floor();";
static const lxl_str sl7517 = {.p = sl7517b, .len = 33U, .cap = 0U};
static char sl7518b[52] = " * Here is the description of some local variables:";
static const lxl_str sl7518 = {.p = sl7518b, .len = 51U, .cap = 0U};
static char sl7519b[70] = " *      jk      jk+1 is the initial number of terms of ipio2[] needed";
