static char sl7527b[64] = " *      jz      local integer variable indicating the number of";
static const lxl_str sl7527 = {.p = sl7527b, .len = 63U, .cap = 0U};
static char sl7528b[39] = " *              terms of ipio2[] used.";
static const lxl_str sl7528 = {.p = sl7528b, .len = 38U, .cap = 0U};
static char sl7529b[23] = " *      jx      nx - 1";
static const lxl_str sl7529 = {.p = sl7529b, .len = 22U, .cap = 0U};
static char sl7530b[67] = " *      jv      index for pointing to the suitable ipio2[] for the";
